const items = $input.all();
const total = items.length;
const corregidas = items.filter(i => i.json.estado_remediacion === 'corregida').length;
const pendientes = items.filter(i => i.json.estado_remediacion === 'pendiente').length;

const filasTabla = items.map(item => {
  const d = item.json;
  const colorEstado = d.estado_remediacion === 'corregida' ? '#28a745' : '#dc3545';
  const textoEstado = d.estado_remediacion === 'corregida' ? 'Corregida' : 'Pendiente';
  return `<tr>
    <td style="padding:8px;border:1px solid #ddd;">${d.cve_id}</td>
    <td style="padding:8px;border:1px solid #ddd;">${d.prioridad}</td>
    <td style="padding:8px;border:1px solid #ddd;">${d.score_final}</td>
    <td style="padding:8px;border:1px solid #ddd;">${d.nombre_equipo || 'Sin asignar'}</td>
    <td style="padding:8px;border:1px solid #ddd;color:${colorEstado};font-weight:bold;">${textoEstado}</td>
  </tr>`;
}).join('');

const tablaHTML = `<table style="border-collapse:collapse;width:100%;font-family:Arial,sans-serif;font-size:13px;">
  <thead>
    <tr style="background-color:#003366;color:white;">
      <th style="padding:10px;border:1px solid #ddd;">CVE</th>
      <th style="padding:10px;border:1px solid #ddd;">Prioridad</th>
      <th style="padding:10px;border:1px solid #ddd;">Score</th>
      <th style="padding:10px;border:1px solid #ddd;">Equipo</th>
      <th style="padding:10px;border:1px solid #ddd;">Estado</th>
    </tr>
  </thead>
  <tbody>${filasTabla}</tbody>
</table>`;

const pendientesDetalle = items
  .filter(i => i.json.estado_remediacion === 'pendiente')
  .map(i => `${i.json.cve_id} (${i.json.nombre_equipo || 'sin asignar'})`)
  .join(', ');

const prompt = `Eres un analista de ciberseguridad redactando un breve resumen ejecutivo para la dirección de BancaSegura S.A. (banco online).
DATOS DEL ANÁLISIS:
- Total vulnerabilidades críticas: ${total}
- Corregidas: ${corregidas}
- Pendientes: ${pendientes}
- Vulnerabilidades que siguen pendientes: ${pendientesDetalle}

Redacta un resumen ejecutivo BREVE (máximo 130 palabras, 2 párrafos) en español, claro y directo para dirección. Requisitos:
- Menciona el progreso concreto (${corregidas} de ${total} corregidas).
- Nombra específicamente qué equipos tienen vulnerabilidades aún pendientes y cuántas.
- Da UNA recomendación concreta y accionable, no genérica.
Evita frases vagas como "mantener seguimiento constante" o "fortalecer procesos". Sé específico. Responde solo con el texto, sin formato JSON.`;

return [{ json: {
  model: "qwen2.5:7b",
  prompt: prompt,
  stream: false,
  tabla_html: tablaHTML,
  total: total,
  corregidas: corregidas,
  pendientes: pendientes,
  email_direccion: items[0].json.email_direccion
} }];

const items = $input.all();
const primerCode = $('Code in JavaScript').first().json;
return items.map(item => {
  return { 
    json: { 
      informe: item.json.response,
      tabla_html: primerCode.tabla_html,
      total: primerCode.total,
      corregidas: primerCode.corregidas,
      pendientes: primerCode.pendientes,
      email_direccion: primerCode.email_direccion
    } 
  };
});

const items = $input.all();
const d = items[0].json;

const htmlCompleto = `<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><style>
body { font-family: Arial, sans-serif; padding: 40px; color: #333; }
h1 { color: #003366; }
table { border-collapse: collapse; width: 100%; font-size: 12px; margin-top: 20px; }
th { background-color: #003366; color: white; padding: 8px; border: 1px solid #ddd; }
td { padding: 8px; border: 1px solid #ddd; }
.resumen { margin: 20px 0; line-height: 1.5; }
</style></head>
<body>
<h1>Informe Ejecutivo de Ciberseguridad</h1>
<p><strong>BancaSegura S.A.</strong></p>
<p>Total: ${d.total} | Corregidas: ${d.corregidas} | Pendientes: ${d.pendientes}</p>
<div class="resumen">${d.informe.replace(/\n/g, '<br>')}</div>
<h2>Detalle de vulnerabilidades</h2>
${d.tabla_html}
</body>
</html>`;

const htmlBase64 = Buffer.from(htmlCompleto).toString('base64');

return [{ json: {
  html_base64: htmlBase64,
  email_direccion: d.email_direccion,
  informe: d.informe,
  tabla_html: d.tabla_html,
  total: d.total,
  corregidas: d.corregidas,
  pendientes: d.pendientes
} }];
